// Code generated by Bequadro. DO NOT EDIT.
// The Bequadro runtime for TypeScript (TS-011). The CLI writes it next to the code it generates (CLI-006).
// Exports whose names start with a lower-case letter, other than write and parse, and the codec types, are for
// generated code only.

/** A buffer is malformed or isn't a buffer for the schema (SER-009). */
export class FlatBufferDataError extends Error {
  override name = "FlatBufferDataError";
}

/** An object graph can't be written (SER-004). */
export class FlatBufferWriteError extends Error {
  override name = "FlatBufferWriteError";
}

export interface WriteOptions {
  /** Write equal strings once (SER-003). */
  readonly shareStrings?: boolean | undefined;
}

export interface ParseOptions {
  /** Return one string per string position in the buffer (SER-011). */
  readonly shareStrings?: boolean | undefined;
}

// Generated code names built-in types through these aliases, so a schema type with the same name can't hide them
/** A byte vector. */
export type Bytes = Uint8Array;
/**
 * A Uint8Array that is the whole of an ArrayBuffer of its own, as write returns, which APIs that don't take a
 * SharedArrayBuffer, such as Blob and fetch, accept without a cast.
 */
export type OwnedBytes = Uint8Array<ArrayBuffer>;
export type View = DataView;

export interface TableCodec<T, TInit> {
  /** The table's fully qualified schema name. */
  readonly name: string;
  write(writer: Writer, value: TInit): number;
  /** A new object with every field present, holding its default or undefined. */
  empty(): T;
  fill(reader: Reader, table: number, value: T): void;
}

export interface StructCodec<T, TInit> {
  readonly name: string;
  readonly size: number;
  readonly alignment: number;
  /**
   * Writes a struct; owner and field name where it is, for messages. The runtime first passes "" as field, and only
   * after an error writes it again with the real path, which throws the same error with that path (writeWithPath).
   */
  write(view: DataView, offset: number, value: TInit, owner: string, field: string): void;
  read(view: DataView, offset: number): T;
}

export interface UnionCodec<T, TInit> {
  readonly name: string;
  /** Whether NONE is a value, which it isn't for a union declared with bequadro_exclude_none. */
  readonly allowsNone: boolean;
  /** Returns the discriminator and the offset of the value, or [0, 0] for NONE (undefined or null). */
  write(writer: Writer, value: TInit | undefined): readonly [number, number];
  /** Reads the member with discriminator type, or NONE (undefined) for 0. */
  read(reader: Reader, type: number, uoffsetPosition: number): T | undefined;
}

/** Serializes value as the root table and returns exactly the buffer. */
export function write<T, TInit>(codec: TableCodec<T, TInit>, value: TInit, options?: WriteOptions): OwnedBytes {
  if (value === null || value === undefined) {
    throw new TypeError(`Cannot serialize ${String(value)} as table '${codec.name}'.`);
  }

  const writer = new Writer(options?.shareStrings === true);
  return writer.finish(writer.writeTable(codec, value));
}

/** Parses a buffer whose root is a table of the codec's type. */
export function parse<T, TInit>(codec: TableCodec<T, TInit>, buffer: Uint8Array, options?: ParseOptions): T {
  if (!isUint8Array(buffer)) {
    throw new TypeError(`Expected a Uint8Array to parse as table '${codec.name}'.`);
  }

  return new Reader(buffer, options?.shareStrings === true).readRoot(codec);
}

/** Casts without a check, for objects generated code knows are complete. */
export function cast<T>(value: unknown): T {
  return value as T;
}

export const notANumber: number = 0 / 0;
export const positiveInfinity: number = 1 / 0;
export const negativeInfinity: number = -1 / 0;

// Scalar kinds, in the order of the schema's scalar types
export const Bool = 0;
export const Int8 = 1;
export const Uint8 = 2;
export const Int16 = 3;
export const Uint16 = 4;
export const Int32 = 5;
export const Uint32 = 6;
export const Int64 = 7;
export const Uint64 = 8;
export const Float32 = 9;
export const Float64 = 10;

const sizes = [1, 1, 1, 2, 2, 4, 4, 8, 8, 4, 8] as const;
const typeNames = ["bool", "byte", "ubyte", "short", "ushort", "int", "uint", "long", "ulong", "float", "double"];
const integerRanges: readonly (readonly [number, number] | undefined)[] = [
  undefined,
  [-128, 127],
  [0, 255],
  [-32768, 32767],
  [0, 65535],
  [-2147483648, 2147483647],
  [0, 4294967295],
];

/** The deepest table nesting that can be parsed, and therefore written. */
const maxDepth = 64;

/** The largest buffer, the same in every Bequadro runtime (SER-012). */
const maxSize = 2147483591;

const inProgress = -1;

const encoder = new TextEncoder();

/** The longest string written a character at a time when it is all ASCII, which is faster than encoding it. */
const shortString = 12;

/**
 * The longest string encoded into the writer's reused scratch array, which saves allocating an array for each string.
 * A longer one is encoded into an array of its own, so the scratch array stays small.
 */
const scratchString = 65536;
// ignoreBOM keeps a leading U+FEFF, which is part of the string, as every other Bequadro runtime does (SER-008)
const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

// The getter of TypedArray.prototype[Symbol.toStringTag] reads an internal slot, so unlike instanceof it recognizes
// typed arrays from another realm (an iframe, or a vm context such as Jest's), and it can't be spoofed
const typedArrayName = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(Uint8Array.prototype), Symbol.toStringTag)!
  .get as (this: unknown) => string | undefined;

/** Whether value is a Uint8Array, including a subclass such as Node's Buffer, from any realm (TS-011). */
function isUint8Array(value: unknown): value is Uint8Array {
  return typedArrayName.call(value) === "Uint8Array";
}

function describe(value: unknown): string {
  if (typeof value === "string") {
    return `the string ${JSON.stringify(value.length > 20 ? value.slice(0, 20) + "..." : value)}`;
  }

  if (typeof value === "bigint") {
    return `${value}n`;
  }

  return typeof value === "object" && value !== null ? "an object" : String(value);
}

function where(owner: string, field: string): string {
  return `field '${field}' of '${owner}'`;
}

/**
 * Checks a scalar of the given kind and returns it as written: floats rounded to their precision. Throws for a value of
 * the wrong type or out of range (TS-011). index is that of a vector element, which messages name, or -1.
 */
export function check(kind: number, value: unknown, table: string, field: string, index = -1): number | bigint | boolean {
  switch (kind) {
    case Bool:
      if (typeof value === "boolean") {
        return value;
      }

      break;
    case Int64:
    case Uint64:
      if (typeof value === "bigint") {
        if ((kind === Int64 ? BigInt.asIntN(64, value) : BigInt.asUintN(64, value)) === value) {
          return value;
        }

        throw new FlatBufferWriteError(
          `${describe(value)} is out of range for ${typeNames[kind]} ${where(table, elementPath(field, index))}.`,
        );
      }

      break;
    case Float32:
      if (typeof value === "number") {
        return Math.fround(value);
      }

      break;
    case Float64:
      if (typeof value === "number") {
        return value;
      }

      break;
    default:
      if (typeof value === "number") {
        const [min, max] = integerRanges[kind]!;
        if (Number.isInteger(value) && value >= min && value <= max) {
          return value;
        }

        throw new FlatBufferWriteError(
          `${describe(value)} is not an integer from ${min} to ${max}, as ${typeNames[kind]} ${where(table, elementPath(field, index))} must be.`,
        );
      }

      break;
  }

  const expected = kind === Bool ? "a boolean" : kind === Int64 || kind === Uint64 ? "a bigint" : "a number";
  throw new FlatBufferWriteError(`Expected ${expected} for ${where(table, elementPath(field, index))}, got ${describe(value)}.`);
}

/** Returns the value of a required field, throwing if it is absent. */
export function required<T>(value: T | null | undefined, table: string, field: string): T {
  if (value === undefined || value === null) {
    throw new FlatBufferWriteError(`Required field '${field}' of table '${table}' is null.`);
  }

  return value;
}

/** Returns the value of a union variant whose member is a table, throwing if it is missing (TS-007). */
export function memberValue<T>(value: T | null | undefined, union: string, label: string): T {
  if (value === undefined || value === null) {
    throw new FlatBufferWriteError(`Expected an object for ${where(union, label)}, got ${describe(value)}.`);
  }

  return value;
}

/** Stores a union's or a union vector's pair of offsets in the slots slot - 1 and slot of offsets. */
export function pair(offsets: number[], slot: number, values: readonly [number, number]): void {
  offsets[slot - 1] = values[0];
  offsets[slot] = values[1];
}

function unionHasNoValue(union: string): FlatBufferWriteError {
  return new FlatBufferWriteError(`Cannot serialize the union '${union}' because it has no value.`);
}

/** Throws for a union variant that can't be written: unknown, or with a kind the union doesn't have. */
export function unwritableUnion(union: string, value: { readonly kind?: unknown; readonly discriminator?: unknown }): never {
  if (value.kind === "unknown") {
    throw new FlatBufferWriteError(
      `Cannot serialize the union '${union}' because it holds an unknown member (discriminator ${String(value.discriminator)}), whose data is not kept when parsing.`,
    );
  }

  throw new FlatBufferWriteError(`The union '${union}' has no member with kind ${describe(value.kind)}.`);
}

export function readStructField(view: DataView, kind: number, offset: number): number | bigint | boolean {
  switch (kind) {
    case Bool:
      return view.getUint8(offset) !== 0;
    case Int8:
      return view.getInt8(offset);
    case Uint8:
      return view.getUint8(offset);
    case Int16:
      return view.getInt16(offset, true);
    case Uint16:
      return view.getUint16(offset, true);
    case Int32:
      return view.getInt32(offset, true);
    case Uint32:
      return view.getUint32(offset, true);
    case Int64:
      return view.getBigInt64(offset, true);
    case Uint64:
      return view.getBigUint64(offset, true);
    case Float32:
      return view.getFloat32(offset, true);
    default:
      return view.getFloat64(offset, true);
  }
}

/**
 * Writes a nested struct, which may be missing from an input object, in which case it is zero. field is the outer
 * struct's path, and member the nested struct's name in it (".position").
 */
export function writeNestedStruct<TInit>(
  codec: StructCodec<unknown, TInit>,
  view: DataView,
  offset: number,
  value: TInit | undefined,
  owner: string,
  field: string,
  member: string,
): void {
  if (value === undefined || value === null) {
    return;
  }

  if (typeof value !== "object") {
    throw new FlatBufferWriteError(`Expected an object for ${where(owner, field + member)}, got ${describe(value)}.`);
  }

  // On the first attempt field is "", and so is the inner struct's, so that its members' paths cost nothing either
  codec.write(view, offset, value, owner, field === "" ? "" : field + member);
}

/**
 * Writes a struct with "" as its path, so that its members' paths cost nothing, and if that throws a
 * FlatBufferWriteError, writes it again with its real path, which throws the same error with the path in its message.
 * The path is field, or field[index] for a vector element; index is -1 otherwise.
 */
function writeStructAt<TInit>(
  codec: StructCodec<unknown, TInit>,
  view: DataView,
  offset: number,
  value: TInit,
  owner: string,
  field: string,
  index: number,
): void {
  try {
    codec.write(view, offset, value, owner, "");
  } catch (error) {
    if (error instanceof FlatBufferWriteError) {
      codec.write(view, offset, value, owner, elementPath(field, index));
    }

    // Reached for any other error, such as one from a getter, or if the retry didn't throw, which only a getter that
    // returns a different value the second time can cause: the original error stands, though its message lacks the path
    throw error;
  }
}

/** A field's path, with the index of a vector element unless index is -1. */
function elementPath(field: string, index: number): string {
  return index === -1 ? field : `${field}[${index}]`;
}

/** Writes a struct field, which may be missing from an input object, in which case it is zero. */
export function writeStructField(
  view: DataView,
  kind: number,
  offset: number,
  value: unknown,
  owner: string,
  field: string,
): void {
  if (value === undefined || value === null) {
    return;
  }

  put(view, kind, offset, check(kind, value, owner, field));
}

function put(view: DataView, kind: number, offset: number, value: number | bigint | boolean): void {
  switch (kind) {
    case Bool:
      view.setUint8(offset, value === true ? 1 : 0);
      break;
    case Int8:
      view.setInt8(offset, value as number);
      break;
    case Uint8:
      view.setUint8(offset, value as number);
      break;
    case Int16:
      view.setInt16(offset, value as number, true);
      break;
    case Uint16:
      view.setUint16(offset, value as number, true);
      break;
    case Int32:
      view.setInt32(offset, value as number, true);
      break;
    case Uint32:
      view.setUint32(offset, value as number, true);
      break;
    case Int64:
      view.setBigInt64(offset, value as bigint, true);
      break;
    case Uint64:
      view.setBigUint64(offset, value as bigint, true);
      break;
    case Float32:
      view.setFloat32(offset, value as number, true);
      break;
    default:
      view.setFloat64(offset, value as number, true);
      break;
  }
}

/**
 * Builds a buffer from the back to the front, exactly as the C# runtime's FlatBufferWriter does, so both write the
 * same bytes (SER-005). Positions are offsets from the end of the buffer, which stay valid as it grows.
 */
export class Writer {
  #buffer: Uint8Array;
  #view: DataView;
  #head: number;
  #minAlign = 1;
  // The offset of each slot's field in the table being written, or 0. Offsets fit, because the buffer is at most
  // maxSize bytes.
  #slots = new Int32Array(16);
  #slotCount = 0;
  #tableStart = 0;
  #depth = 0;
  // The tables written, as each object's index in #writtenCodecs and #writtenOffsets, which is cheaper than an object
  // per table. An offset is inProgress while the table is being written, which is how a cycle is found.
  readonly #tables = new Map<object, number>();
  readonly #writtenCodecs: object[] = [];
  readonly #writtenOffsets: number[] = [];
  /** The offsets of the vtables written, by the hash of their uint16s, in the order they were written. */
  readonly #vtables = new Map<number, number[]>();
  /** The uint16s of the vtable being built, reused for every table. */
  readonly #vtable: number[] = [];
  readonly #strings: Map<string, number> | undefined;
  /** Where strings are encoded before they are copied into the buffer (#encode). */
  #scratch = new Uint8Array(256);

  /** initialCapacity is for tests, which make the buffer grow at every allocation. */
  constructor(shareStrings: boolean, initialCapacity = 1024) {
    this.#buffer = new Uint8Array(initialCapacity);
    this.#view = new DataView(this.#buffer.buffer);
    this.#head = initialCapacity;
    this.#strings = shareStrings ? new Map() : undefined;
  }

  /** The number of bytes written so far. */
  get offset(): number {
    return this.#buffer.length - this.#head;
  }

  finish(root: number): OwnedBytes {
    this.#prep(Math.max(this.#minAlign, 4), 4);
    this.#putUOffset(root);
    return this.#buffer.slice(this.#head);
  }

  /**
   * Writes a table once per object; later calls with the same object return the same offset (SER-003). Returns 0 for
   * an absent table, undefined or null.
   */
  writeTable<TInit>(codec: TableCodec<unknown, TInit>, value: TInit | null | undefined): number {
    if (value === undefined || value === null) {
      return 0;
    }

    if (typeof value !== "object") {
      throw new FlatBufferWriteError(`Expected an object for table '${codec.name}', got ${describe(value)}.`);
    }

    const written = this.#tables.get(value);
    if (written !== undefined) {
      const writtenCodec = this.#writtenCodecs[written]!;
      if (writtenCodec !== codec) {
        throw new FlatBufferWriteError(
          `Cannot serialize one object as two tables: it is written as both '${(writtenCodec as { name: string }).name}' and '${codec.name}'.`,
        );
      }

      const offset = this.#writtenOffsets[written]!;
      if (offset === inProgress) {
        throw new FlatBufferWriteError(
          `Cannot serialize a reference cycle: an object written as '${codec.name}' contains itself.`,
        );
      }

      return offset;
    }

    const index = this.#writtenOffsets.push(inProgress) - 1;
    this.#writtenCodecs.push(codec);
    this.#tables.set(value, index);
    if (++this.#depth > maxDepth) {
      throw new FlatBufferWriteError(
        `Cannot serialize tables nested more than ${maxDepth} levels deep, because the buffer couldn't be parsed: an object written as '${codec.name}' is at level ${this.#depth}.`,
      );
    }

    const offset = codec.write(this, value);
    this.#writtenOffsets[index] = offset;
    this.#depth--;
    return offset;
  }

  /** Writes a struct out of line, as union members are. */
  writeStruct<TInit>(codec: StructCodec<unknown, TInit>, value: TInit, owner: string, field: string): number {
    if (typeof value !== "object" || value === null) {
      throw new FlatBufferWriteError(`Expected an object for ${where(owner, field)}, got ${describe(value)}.`);
    }

    this.#prep(codec.alignment, codec.size);
    const position = this.#allocate(codec.size);
    writeStructAt(codec, this.#view, position, value, owner, field, -1);
    return this.offset;
  }

  /** Writes a string, or returns 0 for an absent one. */
  writeString(value: unknown, table: string, field: string): number {
    if (value === undefined || value === null) {
      return 0;
    }

    if (typeof value !== "string") {
      throw expectedString(table, field, value);
    }

    if (this.#strings === undefined) {
      return this.#writeNewString(value);
    }

    let offset = this.#strings.get(value);
    if (offset === undefined) {
      offset = this.#writeNewString(value);
      this.#strings.set(value, offset);
    }

    return offset;
  }

  #writeNewString(value: string): number {
    // ASCII is its own UTF-8 encoding, so a short ASCII string is copied a character at a time
    const length = value.length;
    if (length <= shortString) {
      let ascii = 0;
      while (ascii < length && value.charCodeAt(ascii) <= 0x7f) {
        ascii++;
      }

      if (ascii === length) {
        this.#prep(4, length + 1);
        this.#allocate(1);
        const position = this.#allocate(length);
        const buffer = this.#buffer; // read after #allocate, which may replace the buffer
        for (let i = 0; i < length; i++) {
          buffer[position + i] = value.charCodeAt(i);
        }

        return this.#putLength(length);
      }
    }

    const bytes = length <= scratchString ? this.#encode(value) : encoder.encode(value);
    this.#prep(4, bytes.length + 1);
    this.#allocate(1);
    const position = this.#allocate(bytes.length);
    this.#buffer.set(bytes, position);
    return this.#putLength(bytes.length);
  }

  /** The UTF-8 bytes of value, in the scratch array, which the next call overwrites. */
  #encode(value: string): Uint8Array {
    // A UTF-16 code unit takes at most 3 bytes, and a surrogate pair 4 for its two units
    const capacity = 3 * value.length;
    if (this.#scratch.length < capacity) {
      this.#scratch = new Uint8Array(Math.max(capacity, 2 * this.#scratch.length));
    }

    // encodeInto replaces lone surrogates with U+FFFD, as encode does
    return this.#scratch.subarray(0, encoder.encodeInto(value, this.#scratch).written);
  }

  // The vector writers return 0, or [0, 0] for unions, for an absent vector

  writeScalarVector(kind: number, values: unknown, table: string, field: string): number {
    if (values === undefined || values === null) {
      return 0;
    }

    const array = this.#array(values, table, field);
    const size = sizes[kind]!;
    this.#prep(Math.max(4, size), size * array.length);
    let position = this.#allocate(size * array.length);
    for (let i = 0; i < array.length; i++, position += size) {
      put(this.#view, kind, position, check(kind, array[i], table, field, i));
    }

    return this.#putLength(array.length);
  }

  writeBytes(values: unknown, table: string, field: string): number {
    if (values === undefined || values === null) {
      return 0;
    }

    if (!isUint8Array(values)) {
      throw new FlatBufferWriteError(`Expected a Uint8Array for ${where(table, field)}, got ${describe(values)}.`);
    }

    this.#prep(4, values.length);
    const position = this.#allocate(values.length);
    this.#buffer.set(values, position);
    return this.#putLength(values.length);
  }

  writeStructVector<TInit>(codec: StructCodec<unknown, TInit>, values: unknown, table: string, field: string): number {
    if (values === undefined || values === null) {
      return 0;
    }

    const array = this.#array(values, table, field);
    this.#prep(Math.max(4, codec.alignment), codec.size * array.length);
    const start = this.#allocate(codec.size * array.length);
    for (let i = 0; i < array.length; i++) {
      const element: unknown = array[i];
      if (element === undefined || element === null) {
        throw nullElement(table, field, codec.name);
      }

      if (typeof element !== "object") {
        throw new FlatBufferWriteError(`Expected an object for ${where(table, elementPath(field, i))}, got ${describe(element)}.`);
      }

      writeStructAt(codec, this.#view, start + i * codec.size, element as TInit, table, field, i);
    }

    return this.#putLength(array.length);
  }

  writeStringVector(values: unknown, table: string, field: string): number {
    if (values === undefined || values === null) {
      return 0;
    }

    const array = this.#array(values, table, field);
    const offsets = new Array<number>(array.length);
    for (let i = 0; i < array.length; i++) {
      const element: unknown = array[i];
      if (element === null || element === undefined) {
        throw nullElement(table, field, "string");
      }

      if (typeof element !== "string") {
        throw expectedString(table, elementPath(field, i), element);
      }

      offsets[i] = this.writeString(element, table, field);
    }

    return this.writeOffsetVector(offsets);
  }

  writeTableVector<TInit>(codec: TableCodec<unknown, TInit>, values: unknown, table: string, field: string): number {
    if (values === undefined || values === null) {
      return 0;
    }

    const array = this.#array(values, table, field);
    const offsets = new Array<number>(array.length);
    for (let i = 0; i < array.length; i++) {
      const element: unknown = array[i];
      if (element === null || element === undefined) {
        throw nullElement(table, field, codec.name);
      }

      offsets[i] = this.writeTable(codec, element as TInit);
    }

    return this.writeOffsetVector(offsets);
  }

  /** Writes a vector of unions as its discriminator vector and its value vector. */
  writeUnionVector<TInit>(
    codec: UnionCodec<unknown, TInit>,
    values: unknown,
    table: string,
    field: string,
  ): readonly [number, number] {
    if (values === undefined || values === null) {
      return [0, 0];
    }

    const array = this.#array(values, table, field);
    const types = new Uint8Array(array.length);
    const offsets = new Array<number>(array.length);
    // Elements are tables written from inside this loop, so this frame is on the stack once per level of nesting: it
    // has as few locals as it can, and no destructuring, which needs many (SER-003)
    for (let i = 0; i < array.length; i++) {
      const written = codec.write(this, unionElement(codec, array[i] as TInit | null | undefined));
      types[i] = written[0];
      offsets[i] = written[1];
    }

    return this.#finishUnionVector(types, offsets);
  }

  #finishUnionVector(types: Uint8Array, offsets: readonly number[]): readonly [number, number] {
    const valuesOffset = this.writeOffsetVector(offsets);
    this.#prep(4, types.length);
    const position = this.#allocate(types.length);
    this.#buffer.set(types, position);
    return [this.#putLength(types.length), valuesOffset];
  }

  /** Writes a vector of uoffsets. An offset of 0, a NONE union element, is written as a literal 0. */
  writeOffsetVector(offsets: readonly number[]): number {
    this.#prep(4, 4 * offsets.length);
    for (let i = offsets.length - 1; i >= 0; i--) {
      const offset = offsets[i]!;
      if (offset === 0) {
        this.#allocate(4);
      } else {
        this.#putUOffset(offset);
      }
    }

    return this.#putLength(offsets.length);
  }

  startTable(slotCount: number): void {
    if (this.#slots.length < slotCount) {
      this.#slots = new Int32Array(Math.max(slotCount, 2 * this.#slots.length)); // zeroed
    } else {
      const slots = this.#slots;
      for (let i = 0; i < slotCount; i++) {
        slots[i] = 0;
      }
    }

    this.#slotCount = slotCount;
    this.#tableStart = this.offset;
  }

  addScalar(slot: number, kind: number, value: number | bigint | boolean): void {
    const size = sizes[kind]!;
    this.#prep(size, size);
    const position = this.#allocate(size);
    put(this.#view, kind, position, value);
    this.#slots[slot] = this.offset;
  }

  /** Adds a scalar field unless it is absent or equal to its default, as the C# writer compares (SER-004). */
  addScalarField(
    slot: number,
    kind: number,
    value: unknown,
    defaultValue: number | bigint | boolean,
    table: string,
    field: string,
  ): void {
    if (value === undefined || value === null) {
      return;
    }

    const checked = check(kind, value, table, field);
    // A NaN default skips only NaN; any other compares with !==, so -0 equals a zero default and NaN is written
    if (defaultValue !== defaultValue ? checked === checked : checked !== defaultValue) {
      this.addScalar(slot, kind, checked);
    }
  }

  /** Adds an optional scalar field (= null in the schema) unless it is absent. */
  addOptionalScalarField(slot: number, kind: number, value: unknown, table: string, field: string): void {
    if (value !== undefined && value !== null) {
      this.addScalar(slot, kind, check(kind, value, table, field));
    }
  }

  /** Adds a union's discriminator unless it is NONE. */
  addUnionType(slot: number, type: number): void {
    if (type !== 0) {
      this.addScalar(slot, Uint8, type);
    }
  }

  /** Adds a struct field unless it is absent. */
  addStruct<TInit>(
    slot: number,
    codec: StructCodec<unknown, TInit>,
    value: TInit | null | undefined,
    table: string,
    field: string,
  ): void {
    if (value === undefined || value === null) {
      return;
    }

    if (typeof value !== "object") {
      throw new FlatBufferWriteError(`Expected an object for ${where(table, field)}, got ${describe(value)}.`);
    }

    this.#prep(codec.alignment, codec.size);
    const position = this.#allocate(codec.size);
    writeStructAt(codec, this.#view, position, value, table, field, -1);
    this.#slots[slot] = this.offset;
  }

  /** Adds an offset field unless the target is 0, which is an absent child. */
  addOffset(slot: number, target: number): void {
    if (target === 0) {
      return;
    }

    this.#prep(4, 4);
    this.#putUOffset(target);
    this.#slots[slot] = this.offset;
  }

  /**
   * Writes the table's soffset and vtable, sharing an identical earlier vtable, and returns the table's offset.
   * `table` is the table's schema name, for the error message.
   */
  endTable(table: string): number {
    this.#prep(4, 4);
    this.#allocate(4);
    const tableOffset = this.offset;

    let usedSlots = this.#slotCount;
    while (usedSlots > 0 && this.#slots[usedSlots - 1] === 0) {
      usedSlots--;
    }

    const vtableSize = (2 + usedSlots) * 2;
    const tableSize = tableOffset - this.#tableStart;
    if (vtableSize > 65535 || tableSize > 65535) {
      throw new FlatBufferWriteError(
        `Cannot serialize an instance of '${table}': a table's inline fields can take at most 65535 bytes, and its vtable at most 65535.`,
      );
    }

    // The vtable's uint16s, in a reused array, hashed so that only vtables with the same hash are compared
    const vtable = this.#vtable;
    vtable[0] = vtableSize;
    vtable[1] = tableSize;
    let hash = (vtableSize * 31 + tableSize) | 0;
    for (let i = 0; i < usedSlots; i++) {
      const slot = this.#slots[i]!;
      const entry = slot === 0 ? 0 : tableOffset - slot;
      vtable[2 + i] = entry;
      hash = (Math.imul(hash, 31) + entry) | 0;
    }

    const vtableOffset = this.#findOrWriteVtable(vtable, 2 + usedSlots, hash);
    this.#view.setInt32(this.#buffer.length - tableOffset, vtableOffset - tableOffset, true);
    return tableOffset;
  }

  /** Returns the offset of the first vtable written with exactly these count uint16s, writing it if there is none. */
  #findOrWriteVtable(vtable: readonly number[], count: number, hash: number): number {
    const candidates = this.#vtables.get(hash);
    if (candidates !== undefined) {
      const view = this.#view;
      const end = this.#buffer.length;
      // In the order they were written, so the first match is the one C# finds too. A vtable stays at the same
      // distance from the end of the buffer as it grows.
      search: for (let c = 0; c < candidates.length; c++) {
        const candidate = candidates[c]!;
        const position = end - candidate;
        // The first uint16 is the vtable's size, so this also rejects vtables of another length
        for (let i = 0; i < count; i++) {
          if (view.getUint16(position + 2 * i, true) !== vtable[i]) {
            continue search;
          }
        }

        return candidate;
      }
    }

    const position = this.#allocate(2 * count);
    const view = this.#view; // read after #allocate, which may replace the buffer
    for (let i = 0; i < count; i++) {
      view.setUint16(position + 2 * i, vtable[i]!, true);
    }

    if (candidates === undefined) {
      this.#vtables.set(hash, [this.offset]);
    } else {
      candidates.push(this.offset);
    }

    return this.offset;
  }

  #array(values: unknown, table: string, field: string): ArrayLike<unknown> {
    if (!Array.isArray(values)) {
      throw new FlatBufferWriteError(`Expected an array for ${where(table, field)}, got ${describe(values)}.`);
    }

    return values as ArrayLike<unknown>;
  }

  /**
   * Pads so that after writing byteCount more bytes the offset is a multiple of alignment, and ensures capacity for
   * the padding plus those bytes.
   */
  #prep(alignment: number, byteCount: number): void {
    if (alignment > this.#minAlign) {
      this.#minAlign = alignment;
    }

    const padding = -(this.offset + byteCount) & (alignment - 1);
    this.#ensureCapacity(padding + byteCount);
    this.#head -= padding;
  }

  /**
   * Reserves byteCount bytes in front of the current data, which are zero, and returns their position. Growing replaces
   * #buffer and #view, so read them only after this returns: `this.#buffer.set(x, this.#allocate(n))` would write into
   * the old buffer, because JavaScript evaluates `this.#buffer` first.
   */
  #allocate(byteCount: number): number {
    this.#ensureCapacity(byteCount);
    this.#head -= byteCount;
    return this.#head;
  }

  #putUOffset(target: number): void {
    const position = this.#allocate(4);
    this.#view.setUint32(position, this.offset - target, true);
  }

  #putLength(count: number): number {
    const position = this.#allocate(4);
    this.#view.setInt32(position, count, true);
    return this.offset;
  }

  #ensureCapacity(byteCount: number): void {
    if (this.#head >= byteCount) {
      return;
    }

    const used = this.offset;
    const required = used + byteCount;
    if (required > maxSize) {
      throw new FlatBufferWriteError(`The serialized buffer would exceed the maximum size of ${maxSize} bytes.`);
    }

    const buffer = new Uint8Array(Math.min(maxSize, Math.max(required, this.#buffer.length * 2)));
    buffer.set(this.#buffer.subarray(this.#head), buffer.length - used);
    this.#buffer = buffer;
    this.#view = new DataView(buffer.buffer);
    this.#head = buffer.length - used;
  }
}

/** A union vector's element, which may be NONE only if the union allows it. */
function unionElement<TInit>(codec: UnionCodec<unknown, TInit>, element: TInit | null | undefined): TInit | undefined {
  if (element === undefined || element === null) {
    if (!codec.allowsNone) {
      throw unionHasNoValue(codec.name);
    }

    return undefined;
  }

  return element;
}

function expectedString(table: string, field: string, value: unknown): FlatBufferWriteError {
  return new FlatBufferWriteError(`Expected a string for ${where(table, field)}, got ${describe(value)}.`);
}

function nullElement(table: string, field: string, elementType: string): FlatBufferWriteError {
  return new FlatBufferWriteError(
    `Cannot serialize a null element in a vector of '${elementType}' in ${where(table, field)}.`,
  );
}

/** The fewest tables a parse reads before it finds tables by an index instead of a Map (Reader.#tableIndex). */
const minTablesForIndex = 4096;

/** Reads a buffer with bounds checking, creating one object per table position (SER-009, SER-011). */
export class Reader {
  readonly #bytes: Uint8Array;
  readonly #view: DataView;
  readonly #length: number;
  // The tables read so far, and each one's codec, by the order in which they were read
  readonly #tableValues: unknown[] = [];
  readonly #tableCodecs: object[] = [];
  // Where each table was read, as its index in #tableValues. Every table is in #tablePositions until the parse has read
  // #tablesForIndex of them. Then #tableIndex, which holds a table's index plus 1 at its position / 4, takes over the
  // tables at positions that are multiples of 4, as every FlatBuffers writer writes them. A Map costs a hash lookup per
  // table, which made it most of the time to parse a buffer of small tables. The index takes 4 bytes per 4 bytes of
  // buffer, so it is only made once the parse has read 1 table per KB of buffer, and at least minTablesForIndex. It
  // then costs at most 1 KB per table read, and a buffer of few tables, such as one mostly holding a large vector,
  // never makes it.
  readonly #tablePositions = new Map<number, number>();
  #tableIndex: Int32Array | undefined;
  #tablesForIndex: number;
  readonly #strings: Map<number, string> | undefined;
  #depth = 0;

  constructor(bytes: Uint8Array, shareStrings: boolean) {
    // A plain Uint8Array of this realm over the same memory, so that slice copies into a plain Uint8Array, where a
    // Buffer's slice would be a view (TS-008)
    this.#bytes = new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    this.#view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    this.#length = bytes.byteLength;
    this.#tablesForIndex = Math.max(minTablesForIndex, this.#length >>> 10);
    this.#strings = shareStrings ? new Map() : undefined;
  }

  readRoot<T, TInit>(codec: TableCodec<T, TInit>): T {
    return this.readTable(codec, 0);
  }

  /** The position of a table's field, or 0 if the field is absent. */
  field(table: number, slot: number): number {
    const vtable = table - this.#view.getInt32(this.#checked(table, 4), true);
    if (vtable < 0 || vtable > this.#length - 4) {
      throw outOfBounds(vtable, 4);
    }

    const vtableSize = this.#view.getUint16(vtable, true);
    const entry = 4 + 2 * slot;
    if (entry + 2 > vtableSize) {
      return 0;
    }

    const fieldOffset = this.#view.getUint16(this.#checked(vtable + entry, 2), true);
    return fieldOffset === 0 ? 0 : table + fieldOffset;
  }

  readScalar(kind: number, position: number): number | bigint | boolean {
    return readStructField(this.#view, kind, this.#checked(position, sizes[kind]!));
  }

  readStruct<T>(codec: StructCodec<T, unknown>, position: number): T {
    return codec.read(this.#view, this.#checked(position, codec.size));
  }

  /** Reads a struct stored out of line, as a union member, whose uoffset is at uoffsetPosition. */
  readStructAt<T>(codec: StructCodec<T, unknown>, uoffsetPosition: number): T {
    return this.readStruct(codec, this.#follow(uoffsetPosition));
  }

  readString(uoffsetPosition: number): string {
    const position = this.#follow(uoffsetPosition);
    if (this.#strings === undefined) {
      return this.#decode(position);
    }

    let value = this.#strings.get(position);
    if (value === undefined) {
      value = this.#decode(position);
      this.#strings.set(position, value);
    }

    return value;
  }

  #decode(position: number): string {
    const [start, length] = this.#vectorAt(position, 1);
    return decoder.decode(this.#bytes.subarray(start, start + length));
  }

  /** Reads a table, returning the object already read from that position if there is one. */
  readTable<T, TInit>(codec: TableCodec<T, TInit>, uoffsetPosition: number): T {
    const position = this.#follow(uoffsetPosition);
    this.#checked(position, 4);
    const index =
      this.#tableIndex !== undefined && (position & 3) === 0
        ? this.#tableIndex[position >>> 2]! - 1
        : (this.#tablePositions.get(position) ?? -1);
    if (index !== -1) {
      const existing = this.#tableCodecs[index]!;
      if (existing !== codec) {
        throw new FlatBufferDataError(
          `The buffer is malformed: the table at ${position} is read as both '${(existing as { name: string }).name}' and '${codec.name}'.`,
        );
      }

      return this.#tableValues[index] as T;
    }

    if (++this.#depth > maxDepth) {
      throw new FlatBufferDataError(`The buffer exceeds the maximum table nesting depth of ${maxDepth}.`);
    }

    // Recorded before fill, so that a table that refers back to itself gets this same object
    const value = codec.empty();
    this.#addTable(position, codec, value);
    codec.fill(this, position, value);
    this.#depth--;
    return value;
  }

  #addTable(position: number, codec: object, value: unknown): void {
    const index = this.#tableValues.push(value) - 1;
    this.#tableCodecs.push(codec);
    if (this.#tableIndex !== undefined && (position & 3) === 0) {
      this.#tableIndex[position >>> 2] = index + 1;
      return;
    }

    this.#tablePositions.set(position, index);
    if (this.#tableIndex === undefined && index + 1 >= this.#tablesForIndex) {
      this.#makeTableIndex();
    }
  }

  /** Moves the tables at positions that are multiples of 4 from #tablePositions to a new #tableIndex. */
  #makeTableIndex(): void {
    let tableIndex: Int32Array;
    try {
      tableIndex = new Int32Array((this.#length >>> 2) + 1);
    } catch (error) {
      if (!(error instanceof RangeError)) {
        throw error;
      }

      // Too large to allocate, so the Map keeps every table
      this.#tablesForIndex = Infinity;
      return;
    }

    for (const [position, index] of this.#tablePositions) {
      if ((position & 3) === 0) {
        tableIndex[position >>> 2] = index + 1;
        this.#tablePositions.delete(position);
      }
    }

    this.#tableIndex = tableIndex;
  }

  readScalarVector<T extends number | bigint | boolean>(kind: number, uoffsetPosition: number): T[] {
    const size = sizes[kind]!;
    const [start, count] = this.#vector(uoffsetPosition, size);
    const result = new Array<T>(count);
    for (let i = 0; i < count; i++) {
      result[i] = readStructField(this.#view, kind, start + i * size) as T;
    }

    return result;
  }

  readBytes(uoffsetPosition: number): Uint8Array {
    const [start, count] = this.#vector(uoffsetPosition, 1);
    return this.#bytes.slice(start, start + count);
  }

  readStructVector<T>(codec: StructCodec<T, unknown>, uoffsetPosition: number): T[] {
    const [start, count] = this.#vector(uoffsetPosition, codec.size);
    const result = new Array<T>(count);
    for (let i = 0; i < count; i++) {
      result[i] = codec.read(this.#view, start + i * codec.size);
    }

    return result;
  }

  readStringVector(uoffsetPosition: number): string[] {
    const [start, count] = this.#vector(uoffsetPosition, 4);
    const result = new Array<string>(count);
    for (let i = 0; i < count; i++) {
      result[i] = this.readString(start + 4 * i);
    }

    return result;
  }

  readTableVector<T, TInit>(codec: TableCodec<T, TInit>, uoffsetPosition: number): T[] {
    // On the stack once per level of nesting, so without destructuring
    const vector = this.#vector(uoffsetPosition, 4);
    const result = new Array<T>(vector[1]);
    for (let i = 0; i < result.length; i++) {
      result[i] = this.readTable(codec, vector[0] + 4 * i);
    }

    return result;
  }

  /**
   * Reads the union field whose value is in slot and whose discriminator is in slot - 1. It is undefined if either is
   * absent or the discriminator is NONE.
   */
  readUnion<T, TInit>(codec: UnionCodec<T, TInit>, table: number, slot: number): T | undefined {
    const typePosition = this.field(table, slot - 1);
    const position = this.field(table, slot);
    if (typePosition === 0 || position === 0) {
      return undefined;
    }

    const type = this.readScalar(Uint8, typePosition) as number;
    return type === 0 ? undefined : codec.read(this, type, position);
  }

  /**
   * Reads the union vector field whose values are in slot and whose discriminators are in slot - 1. It is undefined if
   * either is absent.
   */
  readUnionVector<T, TInit>(codec: UnionCodec<T, TInit>, table: number, slot: number): (T | undefined)[] | undefined {
    // Like the writer's, this frame is on the stack once per level of nesting, so it is kept small
    const vector = this.#unionVector(table, slot);
    if (vector === undefined) {
      return undefined;
    }

    const result = new Array<T | undefined>(vector[2]);
    for (let i = 0; i < result.length; i++) {
      result[i] = codec.read(this, this.#bytes[vector[0] + i]!, vector[1] + 4 * i);
    }

    return result;
  }

  /** The start of the discriminators, the start of the values, and the count of a union vector field, if present. */
  #unionVector(table: number, slot: number): readonly [number, number, number] | undefined {
    const typesUOffsetPosition = this.field(table, slot - 1);
    const valuesUOffsetPosition = this.field(table, slot);
    if (typesUOffsetPosition === 0 || valuesUOffsetPosition === 0) {
      return undefined;
    }

    const [typesStart, typesCount] = this.#vector(typesUOffsetPosition, 1);
    const [valuesStart, valuesCount] = this.#vector(valuesUOffsetPosition, 4);
    if (typesCount !== valuesCount) {
      throw new FlatBufferDataError(
        "The buffer is malformed: a union vector's type and value vectors differ in length.",
      );
    }

    return [typesStart, valuesStart, valuesCount];
  }

  /** Returns the value of a required union or union vector field, throwing if it is absent. */
  required<T>(value: T | undefined, table: string, field: string): T {
    if (value === undefined) {
      throw this.missingRequiredField(table, field);
    }

    return value;
  }

  missingRequiredField(table: string, field: string): FlatBufferDataError {
    return new FlatBufferDataError(`The buffer is malformed: required field '${field}' of table '${table}' is missing.`);
  }

  unknownUnionType(union: string, type: number): FlatBufferDataError {
    return new FlatBufferDataError(`The buffer contains an unknown discriminator ${type} for union '${union}'.`);
  }

  unionNoneNotAllowed(union: string): FlatBufferDataError {
    return new FlatBufferDataError(
      `The buffer contains a NONE element in a vector of union '${union}', which is declared with bequadro_exclude_none.`,
    );
  }

  /** The position of the first element and the element count of the vector whose uoffset is at uoffsetPosition. */
  #vector(uoffsetPosition: number, elementSize: number): readonly [number, number] {
    return this.#vectorAt(this.#follow(uoffsetPosition), elementSize);
  }

  #vectorAt(position: number, elementSize: number): readonly [number, number] {
    const count = this.#view.getInt32(this.#checked(position, 4), true);
    const start = position + 4;
    if (count < 0 || count * elementSize > this.#length - start) {
      throw new FlatBufferDataError(
        `The buffer is malformed: the vector at ${position} with ${count} elements is out of bounds.`,
      );
    }

    return [start, count];
  }

  #follow(uoffsetPosition: number): number {
    const target = uoffsetPosition + this.#view.getUint32(this.#checked(uoffsetPosition, 4), true);
    if (target >= this.#length) {
      throw outOfBounds(target, 0);
    }

    return target;
  }

  #checked(position: number, size: number): number {
    if (position < 0 || position > this.#length - size) {
      throw outOfBounds(position, size);
    }

    return position;
  }
}

function outOfBounds(position: number, size: number): FlatBufferDataError {
  return new FlatBufferDataError(
    `The buffer is malformed: reading ${size} bytes at position ${position} is out of bounds.`,
  );
}

/** Compares numbers as .NET's double.Equals does: NaN equals NaN, and 0 equals -0 (TS-010). */
export function equalNumbers(a: number | undefined, b: number | undefined): boolean {
  return a === b || (a !== a && b !== b);
}

/** Compares two optional values, which are equal when both are undefined, or under equal otherwise. */
export function equalOptional<T>(a: T | undefined, b: T | undefined, equal: (a: T, b: T) => boolean): boolean {
  return a === undefined || b === undefined ? a === b : equal(a, b);
}

/** Compares vectors element by element. undefined isn't equal to an empty vector (TS-010). */
export function equalVectors<T>(
  a: ArrayLike<T> | undefined,
  b: ArrayLike<T> | undefined,
  equal: (a: T, b: T) => boolean,
): boolean {
  if (a === b) {
    return true;
  }

  if (a === undefined || b === undefined || a.length !== b.length) {
    return false;
  }

  for (let i = 0; i < a.length; i++) {
    if (!equal(a[i]!, b[i]!)) {
      return false;
    }
  }

  return true;
}

export function equalIdentical<T>(a: T, b: T): boolean {
  return a === b;
}
